// en/fi/sv texts for assistantAppGuideWarehouse.cjs. The tools' UI (Optælling, which is "Stock count" in English, and Softwareload) is Danish or English (fi/sv users see English),
// so en/fi/sv quote the English button and tab names.
const WAREHOUSE_LOCALIZED = {
  en: {
    title: 'Work Tools',
    summary: 'Work Tools is only in the TCD and TRR hubs (it was called Warehouse Management). It is a small hub of tools: Time card (clock in and out on your tasks with start, break and stop; only managers see the times), Locations (where the pallets are, put away, take the oldest first and refill pick places), Stock count (the quarterly stock count of terminals and accessories in plant D301 with serial-number scanning, approval, SAP physical inventory documents, final reports and an archive of held statuses) and Softwareload (scan the terminals you load on a task with a clock, and the app moves them in SAP when the task is finished; search a serial number, and managers see statistics).',
    where: 'Open the "Work Tools" tile on the front page (only in the TCD and TRR hubs) and choose "Time card", "Locations", "Stock count" or "Softwareload".',
    tasks: {
      timeclock: { title: 'Clock in and out on a task', steps: ['Open "Work Tools" on the front page and choose "Time card".', 'Your task today from the shift schedule is chosen already. Choose another task in the list, or click "New task" to create one (it is added to the shift schedule too).', 'Click "Start". The clock runs, and you can click "Break" and "Resume" as often as you like. Breaks are not counted.', 'Click "Stop" when the task is done. To move on to another task, choose it and click "Switch task": the first is saved and the new one starts in one go.'], notes: 'The clock is saved on M:, so it keeps running if you close the app and can be stopped from another PC. If it has run for more than 10 hours, you are asked at Stop when you really stopped. Saved times can only be seen by managers. "Cancel clock" throws away a clock started by mistake.' },
      'timeclock-overview': { title: 'See registered times and statistics', steps: ['Open "Work Tools" > "Time card" and choose the "Overview and statistics" tab (managers only).', 'Choose the period (today, this week, this month, last month or your own) and optionally a person or a task.', 'See the total time, the number of registrations, the time per task, per person and per day, and who is on the clock right now.', 'Edit or delete a registration in the list at the bottom. The correction is saved with your name.'], notes: 'Only managers (not status managers) see the times. Employees see neither each other\'s nor their own saved times.' },
      'start-status': { title: 'Start a status', steps: ['Open "Work Tools" on the front page and choose "Stock count".', 'Click "Start new status", choose the year and quarter, and click "Start status". Before you start, you can run "Check SAP errors" so errors in SAP are fixed before the count.', 'Everyone in the team can now create counts in the status. Only one status can be in progress at a time.'], notes: 'Only managers and status managers can start, lock and delete a status.' },
      'create-count': { title: 'Create a count', steps: ['Open "Work Tools" > "Stock count" and click "New count" (this needs a status in progress and SAP to be open).', 'Choose storage locations, Unblocked or Blocked, and whether it is terminals or accessories. Blocked stock is only counted in D000.', 'Click "Fetch from SAP". The stock and serial numbers for all of D301 are fetched (about a minute), and you see what has to be counted.', 'Give the count a name and click "Create count". You are responsible, and colleagues can ask to join.'], notes: 'Each storage location and stock type is counted in one count per status only. SAP is only read when a count is created.' },
      'blocked-unblocked': { title: 'Count blocked and unblocked stock', steps: ['Blocked stock only exists on D000 and is counted in its own count, because it is posted separately in SAP.', 'Click "New count", choose "Blocked" under Stock type and D000, and click "Fetch from SAP". Unblocked stock is counted in another count.', 'If you scan a blocked serial number in an unblocked count (or the other way round), you are told which count it belongs to.'], notes: 'Accessories are also only counted in D000. In the overview you can tick "Show only blocked".' },
      'long-serials': { title: 'Long serial numbers for SAP documents', steps: ['TCD only: open "Work Tools" > "Stock count" and choose the "Serial number rules" tab. A manager adds the new terminals (INT…-0) whose SAP document needs the long serial number (ZMS_LONG_SERNO).', 'In the count: choose the "Overview" or "To count document" tab and click "Long" next to the material. The long numbers are looked up in SAP and copied, ready to paste into SAP.', 'Materials without a rule are copied with the short numbers via "Copy".'], notes: 'Scanning always uses the short number, and blocked stock (D000) always uses the short numbers. If SAP has no long number, the short one is copied and you are told.' },
      'scan-serials': { title: 'Scan serial numbers and count quantities', steps: ['Open the count and choose the "Scan serial numbers" tab. Choose or type the location (e.g. "Pallet 14.2").', 'Scan the serial numbers. You are told at once whether the number was found, is missing in SAP, belongs to another count or is in the wrong place.', 'Items without serial numbers are counted on the "Accessories and count lists" tab: choose the material, click a location and type the quantity.', 'Undo a wrong scan with "Undo (Ctrl+Z)", or remove it under "Remove serial number".'], notes: 'Scans are saved locally first and sent to the shared drive, even if the connection drops for a moment. The locations from TCD\'s placement sheet are only suggestions.' },
      'submit-material': { title: 'Count a material and submit it for approval', steps: ['Choose the material under "Material in focus". It is locked to you, so nobody else counts it at the same time.', 'Scan or count the material. To help a colleague, click "Ask to help count".', 'Click "Send for approval". If there is a difference, confirm it and preferably add a comment.'], notes: 'An approved material disappears from the lists, and its figures are frozen.' },
      'approve-materials': { title: 'Approve materials and close a count', steps: ['Open the count and choose the "Approval" tab. "Approve all without a difference" approves every material that matches.', 'Go through the materials with a difference: click "Approve", or "Send back" with a comment if they must be counted again.', 'When everything is approved, the person responsible clicks "Close". The Excel report is made under "Excel report".'], notes: 'Approval freezes the SAP quantity, the counted quantity and the difference. "Reset" removes the approval again.' },
      'sap-documents': { title: 'Create and post SAP physical inventory documents', steps: ['Open the count and choose the "To count document" tab. Click "Fetch today\'s SAP figures" on the day the document is made.', 'Tick approved materials and click "Create SAP document". SAP opens and you press F8 yourself. Then click "Print".', 'An admin (not the person who created the document) clicks "Enter quantity". Serial numbers go to ZMS_COUNT_SERIAL (SAP\'s serial numbers today minus the ones missing at approval), quantities to MI04.', 'Finally a manager clicks "Post". The material document is shown, and the material is marked "Posted in SAP".'], notes: 'At most 20 materials per document. New terminals get a document each, and serial-number and quantity materials are never mixed. The program fills in SAP, but you always press F8, Save or Post yourself. A document can be deleted as long as no quantities have been entered.' },
      'lock-status': { title: 'Approve and lock the status', steps: ['Open the status with "See details". The checklist shows what is missing: open counts and materials that are not approved or posted.', 'When it says "Everything is ready", click "Approve and lock status" and confirm. The final status report and a report per count are saved.', 'The status moves to "Archive". If something must be corrected, click "Unlock" and say why. Locking again makes version 2 of the report.'] },
      archive: { title: 'Archive and difference in percent', steps: ['Open "Work Tools" > "Stock count" and choose the "Archive" tab. It lists every approved and locked status with its reports.', 'Click "See details". The difference is shown as a percentage of the SAP stock, both in pieces and DKK. Over and under both count as difference.', 'The materials table shows SAP, counted, difference, approval and documents. Click a document number to see it in SAP (MI03 or the material document, display only).'], notes: 'Everyone in the team can see the archive.' },
      'sap-check': { title: 'Check SAP errors before a status', steps: ['Open "Work Tools" > "Stock count" and choose the "Check SAP errors" tab. Choose TCD, TRR or all of D301 and click "Check SAP now".', 'The list shows e.g. stock where the quantity does not match the serial numbers, serial numbers in several places and stock without serial numbers. The result is compared with the SAP report ZMS_STOCK_SER_CHK2.', 'Click "Make mail to the SAP team" to send the errors to the person who fixes them. The mail opens in Outlook and you send it yourself.'] },
      'warehouse-roles': { title: 'Appoint an admin, a status manager or a Placerings admin', steps: ['Open "Manager Panel" and choose the "Permissions" tab. The "Work tools roles" card is only shown in the TCD and TRR hubs.', 'Under "Stock count": choose "Admin" for a colleague who should take part in every count without asking, approve participants and enter quantities and serial numbers on SAP documents, or "Status manager" for someone who should have the same rights as a manager in Stock count.', 'Under "Locations": choose "Placerings admin" for a colleague who may maintain locations and undo actions in the log.'], notes: 'Only managers can change the roles, and managers always have every right. The person who creates a SAP document can never enter the quantities on it. A status manager is not a Placerings admin by that alone.' },
      'warehouse-roles-info': { title: 'Roles in Stock count and Locations', steps: ['Admin in Stock count: takes part in every count without asking, approves participants and enters quantities and serial numbers on SAP documents with "Enter quantity". It is always someone other than the person who created the document.', 'Status manager: has the same rights as a manager in Stock count, e.g. starting, locking and deleting a status, approving materials and posting SAP documents.', 'Placerings admin: may maintain locations and undo actions in the log in Locations.'], notes: 'Only managers appoint the three roles (in "Manager Panel" under "Permissions"). Ask your manager if you need one of them.' },
      'locations-put-away': { title: 'Put a pallet away', steps: ['Open "Work Tools" on the front page, choose "Locations" and click "Put a pallet away".', 'Scan or type the 49/50 number and click "Fetch from SAP". Material, quantity and serial numbers are filled in from SAP. Without SAP you type the material and quantity yourself.', 'Choose one of the suggested places (fixed place, near the same material or free), or type the place.', 'Click "Add next pallet" for more pallets, and "Save all" at the end.'], notes: 'The date is today and can be changed. Reserved and deactivated places are never suggested. TCD and TRR have separate locations.' },
      'locations-take': { title: 'Take a pallet (FIFO)', steps: ['Open "Work Tools" > "Locations" and click "Take".', 'Search or scan the material. The pallets are listed oldest first, so you run FIFO.', 'Click "Take the whole pallet", or type a quantity and click "Take X". If you choose a younger pallet, you are shown the older one and can click "Take anyway".', 'If the material is on shelves, they are listed under "On shelves": type a quantity and click "Take X", or click "Take all".'] },
      'locations-refill': { title: 'Refill a pick place', steps: ['When a box at the work station is empty: open "Work Tools" > "Locations" and click "Refill a pick place".', 'Choose the pick place (and the material if the place has several). The suggestion is the oldest reserve pallet with the same material (FIFO).', 'Fetch the box and click "Refilled from …". Type a quantity if you only took part of the pallet. If you choose a younger pallet, the older one is shown and you can click "Refill anyway".'], notes: 'Pick places have no FIFO and no quantity themselves; FIFO applies to the pallets they are refilled from. You can also ask Hubert: "what do I refill H26 with?".' },
      'locations-find': { title: 'Find a material', steps: ['Open "Work Tools" > "Locations" and type in the search field: material number, description, location, 49/50 number or serial number. With a scanner a single hit opens at once.', 'The material card shows the work station, the pick place, the reserve pallets oldest first and the total quantity. The location card shows what stands on the place.', 'On the pallet card you can click "Edit", "Move" or "Change storage location". Everything goes into the history.'], notes: 'You can also ask Hubert, e.g. "where is R162-0717?" or "what is on A2.4?".' },
      'locations-create': { title: 'Create locations', steps: ['Open "Work Tools" > "Locations" and click "Manage locations" (managers and Placerings admins).', 'Click "Create location" for one place: name, type, purpose (reserve, pick place, work station or reserved) and any fixed materials. The type decides the place: a pallet place holds 1 pallet, a floor has no limit, and a shelf holds material and quantity. A pick place needs its materials.', 'Click "Create series" for many places at once, e.g. prefix C, aisles 1–20 and places 1–6 gives C1.1 … C20.6.', 'Edit, deactivate or set labels (e.g. "Sluse oppe") from the list. Everything can be corrected afterwards.'], notes: 'TRR creates every location here from scratch; TCD can import the placement sheet.' },
      'locations-import': { title: 'Import the placement sheet', steps: ['TCD only: open "Work Tools" > "Locations" > "Manage locations" and click "Import the placement sheet". SAP must be open.', 'Click "Read the sheet and check in SAP". The Hub reads the newest placement sheet on M: (read only) and fetches every material description from SAP.', 'Look through the preview: the number of locations and pallets, and warnings such as materials that do not exist in SAP. Click "Import".'], notes: 'The sheet can be imported again with "Replace all" until the locations are in use. Stock count still reads the sheet itself until you decide to use Locations.' },
      'locations-shelf-put': { title: 'Put on a shelf', steps: ['Open "Work Tools" > "Locations" and click "Put on shelf".', 'Scan or type the shelf, e.g. "E9 H5" (rack E9, shelf 5).', 'Choose the material (suggestions with the description as you type) and type the quantity – or scan the 49/50 number and click "Get from SAP". If the material is already there, the quantity is added. Click "Save". If the number has several materials, they are shown as buttons with their quantity: save them one at a time and the next is chosen by itself.'], notes: 'A shelf holds material and quantity – no age or FIFO. Take from a shelf under "Take", and move between shelves under "Move" or on the shelf card.' },
      'locations-rack-create': { title: 'Create a rack', steps: ['Open "Work Tools" > "Locations" > "Manage locations" and click "Create rack" (managers and Placerings admins).', 'Type the name (e.g. E9), the number of shelves (1–20), the area and the purpose (storage or pick), and click "Create". The shelves are named E9 H1, E9 H2 …', 'On the rack card, add a shelf with "Add shelf" and remove the empty top one with "Remove shelf".'] },
      'locations-delete': { title: 'Delete locations', steps: ['Open "Work Tools" > "Locations" > "Manage locations" (managers and Placerings admins).', 'One location: open it and click "Delete". A rack: open the rack card and click "Delete rack".', 'Many: filter (e.g. area and "Only empty"), click "Select all in the search" or select the rows, and click "Delete selected".'], notes: 'Only empty locations are deleted; a place with pallets or goods stays and you are told why. The deletion is logged and can be undone.' },
      'softwareload-start': { title: 'Start a softwareload task', steps: ['Open "Work Tools" on the front page and choose "Softwareload". The "My task" tab is open.', 'Choose the type "Softwareload + keyload", "Softwareload" or "Keyload", and choose "In KIF" or "Outside KIF".', 'Choose the target from the list under "Target (storage location)". The list shows SAP\'s description and whether the location belongs to TCD or TRR. Type the version under "Software version" and click "Start".', 'The clock is running now. Scan every terminal in the "Scan serial number" field. You can click "Break" and "Resume", and you remove a wrong serial number with the bin.'], notes: 'If your time card is running, it is stopped when you start, so the time is not counted twice. If you start the time card, the softwareload task takes a break. In KIF every terminal is moved via D005 before it reaches the target. Outside KIF they are moved straight to the target. Type, KIF and target are remembered for next time. "Cancel" throws the task away without saving the time or moving anything.' },
      'softwareload-failed': { title: 'Mark a terminal as failed', steps: ['Find the terminal in the "Scanned serial numbers" list of your running task, and click "Failed".', 'Write in the note what is wrong, e.g. that it does not load, and click "Mark as failed".', 'The terminal now shows "Failed" and the note. Click "Undo failed" if it was a mistake.'], notes: 'When the task is finished, a new terminal (the material ends in -0) goes to D000 and blocked stock, and a used one (-R) goes to D002. In KIF they go via D005. If the material is neither -0 nor -R, the terminal must be handled manually.' },
      'softwareload-edit': { title: 'Correct a running task', steps: ['Click "Edit task" on your running task under "My task". The button works when every scan is saved.', 'Correct the type, "In KIF" or "Outside KIF", the target and the software version. The fields are the same as at start and are filled in with what you chose.', 'Click "Save the correction". The task shows the new choices, and the time and the scanned serial numbers stay.'], notes: 'You can correct the task while it runs and until you click "Finish task". Nothing is moved in SAP before then, so finishing uses the new choices. If you choose "In KIF" in the correction, the whole task goes via D005. A task waiting for SAP cannot be corrected. The correction is shown with the task in the statistics.' },
      'softwareload-finish': { title: 'Finish and move in SAP', steps: ['When every terminal is scanned, click "Finish task". The app looks the terminals up in SAP and shows how they will be moved. Nothing is moved yet and the time is still running.', 'Check the groups: to the target, failed new ones to D000 and blocked stock, failed used ones to D002, and problems such as "Not found in SAP" or blocked stock, which are not moved. In KIF everything goes via D005.', 'Click "Finish and move in SAP". The confirmation shows the groups with their counts. Click "Finish and move": the time stops and the app moves all the terminals in SAP in one go. Do not close SAP meanwhile.', 'The result shows every serial number with its outcome and material documents. Click "Done".'], notes: 'If SAP does not answer, e.g. because you are logged out, click "Stop the time now, move in SAP later" on the running task or on the finish screen. The time stops, nothing is looked up in SAP, and the task waits on the "Waiting for SAP" tab. It also waits there if SAP is closed during the move. Click "Continue in SAP" when SAP is ready: the app looks the terminals up and shows the plan first. Click "Move in SAP" and confirm, and exactly the plan shown is moved. What is already moved is not moved again. If SAP has the terminals elsewhere than in the plan you saw, nothing is moved and the new plan is shown. A manager can click "Give up" and write a reason, so the rest stands as given up.' },
      'softwareload-kif': { title: 'Move into KIF', steps: ['Open "Work Tools" > "Softwareload" and choose the "Move into KIF" tab.', 'Scan or paste the serial numbers, one per line. You can also type a material document under "Or a material document", and then the serial numbers of the document are used.', 'Click "Show overview". The app looks the terminals up in SAP and shows what is moved to D005, what is already there and what cannot be moved.', 'Click "Move to D005". The result shows every serial number with the material document.'], notes: 'Use it to move terminals to D005 ahead of time, before they are loaded. Terminals in blocked stock and serial numbers not found in SAP are not moved.' },
      'softwareload-search': { title: 'Search a serial number', steps: ['Open "Work Tools" > "Softwareload" and choose the "Search serial number" tab.', 'Scan or type the serial number and click "Search". The search covers both TCD and TRR.', 'Every load and every move into KIF is shown with who, when, type, software, in KIF or outside KIF, from and to, and the material documents.'], notes: 'If the terminal was marked as failed, the note is shown too.' },
      'softwareload-stats': { title: 'See softwareload statistics', steps: ['Open "Work Tools" > "Softwareload" and choose the "Statistics" tab (managers only).', 'Choose the period (today, this week, this month, last month or your own) and optionally a person, a type, a software version and a material.', 'See the comments on the period at the top, the number of tasks, loaded, failed and terminals per hour, a table per person and type, a table per material and the list of tasks with their times.'], notes: 'Only managers (not status managers) see the statistics, and they see the whole team\'s tasks. The pace counts terminals per working hour. Only those marked as failed are left out. Those SAP refused are also shown apart. When a task has several materials, its time is shared out on them by the number of terminals.' },
      'softwareload-comment': { title: 'Add a comment on a period', steps: ['Open "Work Tools" > "Softwareload", choose the "Statistics" tab and choose the period the comment is about.', 'Click "Add comment". The period is the chosen month. Choose another month under "Whole month", or choose "Own dates" with from and to.', 'Type a material number and a software version if the comment is only about them. Without them it concerns the whole period.', 'Write the comment, e.g. that new software for a material took longer to load, and click "Save the comment".'], notes: 'Comments that fall in the period and fit the filters are shown above the numbers, and the tasks and materials they are about get a small speech bubble. Click "Edit" or "Delete" on a comment to edit or delete it. Only managers can write, edit and delete comments, and they belong to the team. Who wrote, edited and deleted them and when is saved.' },
      'softwareload-delete': { title: 'Delete a task or KIF move', steps: ['Open "Work Tools" > "Softwareload". You delete a finished task on the "Statistics" tab: click the task so it opens, and click "Delete".', 'You also find a move into KIF or a task on the "Search serial number" tab: search one of its serial numbers and click "Delete" on the line. "Delete" on a load deletes the whole task, not only the line.', 'The confirmation shows what is deleted. Click "Delete". The list is updated, and the task or the move no longer counts in the statistics and the search.'], notes: 'Only managers can delete, and only in their own team. Use it for test data, for example. SAP is not changed: the moves and the material documents are still in SAP. A task that is running or waiting for SAP cannot be deleted. Who deleted what and when is saved.' },
    },
  },
  fi: {
    title: 'Työkalut',
    summary: 'Työkalut on vain TCD- ja TRR-hubissa (sen nimi oli ennen Varastonhallinta). Se on pieni työkalujen hub: Time card (leimauskortti: leimaa sisään ja ulos tehtävillesi aloituksella, tauolla ja lopetuksella; vain managerit näkevät ajat), Locations (sijainnit: missä lavat ovat, lavan paikalleen laitto, vanhin ensin ja keräilypaikkojen täyttö), Stock count (neljännesvuosittainen päätteiden ja tarvikkeiden inventointi tehtaalla D301, sarjanumeroiden skannaus, hyväksyntä, SAP-inventointiasiakirjat, lopulliset raportit ja arkisto pidetyistä statuksista) ja Softwareload (skannaa lataamasi päätteet tehtävälle, jossa kello käy, ja sovellus siirtää ne SAPissa, kun tehtävä päätetään; hae sarjanumerolla, ja managerit näkevät tilastot). Näkymät ovat englanniksi.',
    where: 'Avaa etusivulla ruutu "Työkalut" (vain TCD- ja TRR-hubissa) ja valitse "Time card", "Locations", "Stock count" tai "Softwareload".',
    tasks: {
      timeclock: { title: 'Leimaa sisään ja ulos tehtävälle', steps: ['Avaa etusivulta "Työkalut" ja valitse "Time card".', 'Tämän päivän tehtäväsi vuorolistasta on valittu valmiiksi. Valitse luettelosta toinen tehtävä tai luo uusi valitsemalla "New task" (se lisätään myös vuorolistaan).', 'Valitse "Start". Kello käy, ja voit valita "Break" ja "Resume" niin usein kuin haluat. Taukoja ei lasketa.', 'Valitse "Stop", kun tehtävä on valmis. Siirtyäksesi toiseen tehtävään valitse se ja valitse "Switch task": ensimmäinen tallennetaan ja uusi alkaa samalla kertaa.'], notes: 'Kello tallennetaan M:-asemalle, joten se jatkaa, vaikka suljet sovelluksen, ja sen voi pysäyttää toiselta PC:ltä. Jos se on käynyt yli 10 tuntia, Stop kysyy, milloin todella lopetit. Tallennetut ajat näkevät vain managerit. "Cancel clock" poistaa vahingossa käynnistetyn kellon.' },
      'timeclock-overview': { title: 'Katso kirjatut ajat ja tilastot', steps: ['Avaa "Työkalut" > "Time card" ja valitse välilehti "Overview and statistics" (vain managerit).', 'Valitse jakso (tänään, tämä viikko, tämä kuukausi, viime kuukausi tai oma) ja halutessasi henkilö tai tehtävä.', 'Näet kokonaisajan, kirjausten määrän, ajan tehtävittäin, henkilöittäin ja päivittäin sekä sen, kuka on juuri nyt kellossa.', 'Muokkaa tai poista kirjaus alareunan luettelosta. Korjaus tallennetaan nimelläsi.'], notes: 'Vain managerit (eivät status managerit) näkevät ajat. Työntekijät eivät näe toistensa eivätkä omia tallennettuja aikojaan.' },
      'start-status': { title: 'Aloita status', steps: ['Avaa etusivulta "Työkalut" ja valitse "Stock count".', 'Valitse "Start new status", vuosi ja vuosineljännes, ja valitse "Start status". Ennen aloitusta voit ajaa "Check SAP errors", jotta SAP-virheet korjataan ennen inventointia.', 'Nyt kaikki tiimissä voivat luoda inventointeja statukseen. Käynnissä voi olla vain yksi status kerrallaan.'], notes: 'Vain managerit ja status managerit voivat aloittaa, lukita ja poistaa statuksen.' },
      'create-count': { title: 'Luo inventointi', steps: ['Avaa "Työkalut" > "Stock count" ja valitse "New count" (vaatii käynnissä olevan statuksen ja avoimen SAP:n).', 'Valitse varastopaikat, Unblocked tai Blocked, ja onko kyse päätteistä vai tarvikkeista. Blocked-varasto inventoidaan vain paikassa D000.', 'Valitse "Fetch from SAP". Koko D301:n saldot ja sarjanumerot haetaan (noin minuutti), ja näet, mitä pitää laskea.', 'Anna inventoinnille nimi ja valitse "Create count". Olet vastuuhenkilö, ja kollegat voivat pyytää päästä mukaan.'], notes: 'Jokainen varastopaikka ja varastotyyppi inventoidaan vain yhdessä inventoinnissa statusta kohden. SAP:sta luetaan vain, kun inventointi luodaan.' },
      'blocked-unblocked': { title: 'Inventoi blocked- ja unblocked-varasto', steps: ['Blocked-varasto on vain paikassa D000, ja se inventoidaan omassa inventoinnissaan, koska se kirjataan SAP:ssa erikseen.', 'Valitse "New count", valitse kohdasta Stock type "Blocked" ja D000, ja valitse "Fetch from SAP". Unblocked-varasto inventoidaan toisessa inventoinnissa.', 'Jos skannaat blocked-sarjanumeron unblocked-inventoinnissa (tai toisin päin), näet, mihin inventointiin se kuuluu.'], notes: 'Myös tarvikkeet inventoidaan vain paikassa D000. Yleiskuvassa voit valita "Show only blocked".' },
      'long-serials': { title: 'Pitkät sarjanumerot SAP-asiakirjoihin', steps: ['Vain TCD: avaa "Työkalut" > "Stock count" ja valitse välilehti "Serial number rules". Manager lisää uudet päätteet (INT…-0), joiden SAP-asiakirjaan tarvitaan pitkä sarjanumero (ZMS_LONG_SERNO).', 'Inventoinnissa: valitse välilehti "Overview" tai "To count document" ja valitse materiaalin kohdalla "Long". Pitkät numerot haetaan SAP:sta ja kopioidaan valmiiksi liitettäväksi SAP:iin.', 'Materiaalit ilman sääntöä kopioidaan lyhyillä numeroilla valinnalla "Copy".'], notes: 'Skannauksessa käytetään aina lyhyttä numeroa, ja blocked-varasto (D000) käyttää aina lyhyitä numeroita. Jos SAP:ssa ei ole pitkää numeroa, lyhyt kopioidaan ja saat siitä tiedon.' },
      'scan-serials': { title: 'Skannaa sarjanumerot ja laske määrät', steps: ['Avaa inventointi ja valitse välilehti "Scan serial numbers". Valitse tai kirjoita sijainti (esim. "Pallet 14.2").', 'Skannaa sarjanumerot. Näet heti, löytyikö numero, puuttuuko se SAP:sta, kuuluuko se toiseen inventointiin vai onko se väärässä paikassa.', 'Tuotteet ilman sarjanumeroa lasketaan välilehdellä "Accessories and count lists": valitse materiaali, valitse sijainti ja kirjoita määrä.', 'Peru väärä skannaus valinnalla "Undo (Ctrl+Z)" tai poista se kohdassa "Remove serial number".'], notes: 'Skannaukset tallennetaan ensin paikallisesti ja lähetetään jaetulle levylle, vaikka yhteys katkeaisi hetkeksi. TCD:n sijoitustaulukon sijainnit ovat vain ehdotuksia.' },
      'submit-material': { title: 'Laske materiaali ja lähetä se hyväksyttäväksi', steps: ['Valitse materiaali kohdassa "Material in focus". Se lukitaan sinulle, jotta kukaan muu ei laske sitä samaan aikaan.', 'Skannaa tai laske materiaali loppuun. Jos haluat auttaa kollegaa, valitse "Ask to help count".', 'Valitse "Send for approval". Jos on erotus, vahvista se ja kirjoita mieluiten kommentti.'], notes: 'Hyväksytty materiaali katoaa listoilta, ja sen luvut jäädytetään.' },
      'approve-materials': { title: 'Hyväksy materiaalit ja päätä inventointi', steps: ['Avaa inventointi ja valitse välilehti "Approval". "Approve all without a difference" hyväksyy kaikki täsmäävät materiaalit.', 'Käy läpi erotukselliset materiaalit: valitse "Approve" tai "Send back" kommentin kanssa, jos ne pitää laskea uudelleen.', 'Kun kaikki on hyväksytty, vastuuhenkilö valitsee "Close". Excel-raportti tehdään kohdassa "Excel report".'], notes: 'Hyväksyntä jäädyttää SAP-määrän, lasketun määrän ja erotuksen. "Reset" poistaa hyväksynnän.' },
      'sap-documents': { title: 'Luo ja kirjaa SAP-inventointiasiakirjat', steps: ['Avaa inventointi ja valitse välilehti "To count document". Valitse "Fetch today\'s SAP figures" sinä päivänä, kun asiakirja tehdään.', 'Valitse hyväksytyt materiaalit ja valitse "Create SAP document". SAP avautuu, ja painat itse F8. Valitse sitten "Print".', 'Admin (ei asiakirjan luoja) valitsee "Enter quantity". Sarjanumerot menevät ZMS_COUNT_SERIALiin (SAP:n tämän päivän sarjanumerot ilman hyväksynnässä puuttuneita), määrät MI04:ään.', 'Lopuksi manager valitsee "Post". Materiaaliasiakirja näytetään, ja materiaalin kohdalla lukee "Posted in SAP".'], notes: 'Enintään 20 materiaalia asiakirjaa kohden. Uudet päätteet saavat kukin oman asiakirjan, eikä sarjanumero- ja määrämateriaaleja koskaan sekoiteta. Ohjelma täyttää SAP:n, mutta painat aina itse F8, Save tai Post. Asiakirjan voi poistaa, kunhan määriä ei ole syötetty.' },
      'lock-status': { title: 'Hyväksy ja lukitse status', steps: ['Avaa status valinnalla "See details". Tarkistuslista näyttää, mitä puuttuu: avoimet inventoinnit ja materiaalit, joita ei ole hyväksytty tai kirjattu.', 'Kun lukee "Everything is ready", valitse "Approve and lock status" ja vahvista. Lopullinen statusraportti ja raportti jokaisesta inventoinnista tallennetaan.', 'Status siirtyy kohtaan "Archive". Jos jotain pitää korjata, valitse "Unlock" ja kerro syy. Uusi lukitus tekee raportista version 2.'] },
      archive: { title: 'Arkisto ja erotus prosentteina', steps: ['Avaa "Työkalut" > "Stock count" ja valitse välilehti "Archive". Siinä ovat kaikki hyväksytyt ja lukitut statukset raportteineen.', 'Valitse "See details". Erotus näytetään prosentteina SAP-saldosta sekä kappaleina että kruunuina (DKK). Yli- ja alijäämä lasketaan molemmat erotukseksi.', 'Materiaalitaulukossa näkyvät SAP, laskettu, erotus, hyväksyntä ja asiakirjat. Valitse asiakirjan numero nähdäksesi sen SAP:ssa (MI03 tai materiaaliasiakirja, vain katselu).'], notes: 'Kaikki tiimissä voivat katsoa arkistoa.' },
      'sap-check': { title: 'Tarkista SAP-virheet ennen statusta', steps: ['Avaa "Työkalut" > "Stock count" ja valitse välilehti "Check SAP errors". Valitse TCD, TRR tai koko D301 ja valitse "Check SAP now".', 'Luettelossa näkyy esim. varasto, jossa määrä ei täsmää sarjanumeroiden kanssa, sarjanumerot useassa paikassa ja varasto ilman sarjanumeroita. Tulosta verrataan SAP-raporttiin ZMS_STOCK_SER_CHK2.', 'Valitse "Make mail to the SAP team" lähettääksesi virheet korjaajalle. Viesti avautuu Outlookissa, ja lähetät sen itse.'] },
      'warehouse-roles': { title: 'Nimeä admin, status manager tai Placerings admin', steps: ['Avaa "Johtajapaneeli" ja valitse välilehti "Lupa". Kortti "Työkalujen roolit" näkyy vain TCD- ja TRR-hubissa.', 'Kohdassa "Inventointi": valitse "Admin" kollegalle, joka on mukana kaikissa inventoinneissa pyytämättä, hyväksyy osallistujat ja saa syöttää määrät ja sarjanumerot SAP-asiakirjoihin, tai "Status manager" henkilölle, jolla on samat oikeudet kuin managerilla inventoinnissa.', 'Kohdassa "Sijainnit": valitse "Placerings admin" kollegalle, joka saa ylläpitää sijainteja ja perua toimintoja lokissa.'], notes: 'Vain managerit voivat muuttaa rooleja, ja managereilla on aina kaikki oikeudet. SAP-asiakirjan luoja ei voi koskaan itse syöttää siihen määriä. Status manager ei pelkästään sen vuoksi ole Placerings admin.' },
      'warehouse-roles-info': { title: 'Inventoinnin ja sijaintien roolit', steps: ['Admin inventoinnissa: on mukana kaikissa inventoinneissa pyytämättä, hyväksyy osallistujat ja syöttää määrät ja sarjanumerot SAP-asiakirjoihin valitsemalla "Enter quantity". Se on aina joku muu kuin asiakirjan luoja.', 'Status manager: hänellä on inventoinnissa samat oikeudet kuin managerilla, esim. statuksen aloittaminen, lukitseminen ja poistaminen, materiaalien hyväksyminen ja SAP-asiakirjojen kirjaaminen.', 'Placerings admin: saa ylläpitää sijainteja ja perua toimintoja sijaintien lokissa.'], notes: 'Vain managerit nimeävät nämä kolme roolia ("Johtajapaneeli", välilehti "Lupa"). Kysy managerilta, jos tarvitset jonkin niistä.' },
      'locations-put-away': { title: 'Laita lava paikalleen', steps: ['Avaa etusivulta "Työkalut", valitse "Locations" ja valitse "Put a pallet away".', 'Skannaa tai kirjoita 49/50-numero ja valitse "Fetch from SAP". Materiaali, määrä ja sarjanumerot täytetään SAP:sta. Ilman SAP:ia kirjoitat materiaalin ja määrän itse.', 'Valitse yksi ehdotetuista paikoista (kiinteä paikka, saman materiaalin lähellä tai vapaa) tai kirjoita paikka.', 'Valitse "Add next pallet" lisätäksesi lavoja ja lopuksi "Save all".'], notes: 'Päivämäärä on tänään ja sitä voi muuttaa. Varattuja ja poistettuja paikkoja ei koskaan ehdoteta. TCD:llä ja TRR:llä on omat sijaintinsa.' },
      'locations-take': { title: 'Ota lava (FIFO)', steps: ['Avaa "Työkalut" > "Locations" ja valitse "Take".', 'Hae tai skannaa materiaali. Lavat näytetään vanhin ensin, joten noudatat FIFO-periaatetta.', 'Valitse "Take the whole pallet" tai kirjoita määrä ja valitse "Take X". Jos valitset nuoremman lavan, näet vanhemman ja voit valita "Take anyway".', 'Jos materiaalia on hyllyillä, ne näkyvät kohdassa "On shelves": kirjoita määrä ja valitse "Take X" tai "Take all".'] },
      'locations-refill': { title: 'Täytä keräilypaikka', steps: ['Kun työpisteen laatikko on tyhjä: avaa "Työkalut" > "Locations" ja valitse "Refill a pick place".', 'Valitse keräilypaikka (ja materiaali, jos paikalla on useita). Ehdotus on vanhin saman materiaalin varalava (FIFO).', 'Hae laatikko ja valitse "Refilled from …". Kirjoita määrä, jos otit vain osan lavasta. Jos valitset nuoremman lavan, vanhempi näytetään ja voit valita "Refill anyway".'], notes: 'Keräilypaikoilla ei itsellään ole FIFO:a eikä määrää; FIFO koskee lavoja, joista ne täytetään. Voit myös kysyä Hubertilta: "millä täytän H26?".' },
      'locations-find': { title: 'Etsi materiaali', steps: ['Avaa "Työkalut" > "Locations" ja kirjoita hakukenttään materiaalinumero, kuvaus, sijainti, 49/50-numero tai sarjanumero. Skannerilla yksittäinen osuma avautuu heti.', 'Materiaalikortti näyttää työpisteen, keräilypaikan, varalavat vanhin ensin ja kokonaismäärän. Sijaintikortti näyttää, mitä paikalla on.', 'Lavakortilla voit valita "Edit", "Move" tai "Change storage location". Kaikki tallentuu historiaan.'], notes: 'Voit myös kysyä Hubertilta, esim. "missä R162-0717 on?".' },
      'locations-create': { title: 'Luo sijainnit', steps: ['Avaa "Työkalut" > "Locations" ja valitse "Manage locations" (managerit ja Placerings adminit).', 'Valitse "Create location" yhdelle paikalle: nimi, tyyppi, tarkoitus (reserve, pick place, work station tai reserved) ja mahdolliset kiinteät materiaalit. Tyyppi ratkaisee: lavapaikalle mahtuu 1 lava, lattialla ei ole rajaa ja hyllyllä on materiaali ja määrä. Keräilypaikka tarvitsee materiaalinsa.', 'Valitse "Create series" monelle paikalle kerralla, esim. etuliite C, käytävät 1–20 ja paikat 1–6 antavat C1.1 … C20.6.', 'Muokkaa, poista käytöstä tai lisää merkintöjä (esim. "Sluse oppe") listasta. Kaiken voi korjata jälkikäteen.'], notes: 'TRR luo kaikki sijainnit tässä alusta alkaen; TCD voi tuoda sijoitustaulukon.' },
      'locations-import': { title: 'Tuo sijoitustaulukko', steps: ['Vain TCD: avaa "Työkalut" > "Locations" > "Manage locations" ja valitse "Import the placement sheet". SAP:n on oltava auki.', 'Valitse "Read the sheet and check in SAP". Hub lukee uusimman sijoitustaulukon M:-levyltä (vain luku) ja hakee kaikkien materiaalien kuvaukset SAP:sta.', 'Käy esikatselu läpi: sijaintien ja lavojen määrä sekä varoitukset, kuten materiaalit, joita ei ole SAP:ssa. Valitse "Import".'], notes: 'Taulukon voi tuoda uudelleen valinnalla "Replace all", kunnes sijainnit ovat käytössä. Inventointi lukee edelleen itse taulukkoa, kunnes päätätte ottaa sijainnit käyttöön.' },
      'locations-shelf-put': { title: 'Laita hyllylle', steps: ['Avaa "Työkalut" > "Locations" ja valitse "Put on shelf".', 'Skannaa tai kirjoita hylly, esim. "E9 H5" (hyllykkö E9, hylly 5).', 'Valitse materiaali (ehdotukset kuvauksineen kirjoittaessa) ja kirjoita määrä – tai skannaa 49/50-numero ja valitse "Get from SAP". Jos materiaali on jo hyllyllä, määrä lisätään. Valitse "Save". Jos numerossa on useita materiaaleja, ne näkyvät painikkeina määrineen: tallenna ne yksi kerrallaan, niin seuraava valitaan itsestään.'], notes: 'Hyllyllä on materiaali ja määrä – ei ikää eikä FIFO-järjestystä. Ota hyllyltä kohdassa "Take" ja siirrä hyllyjen välillä kohdassa "Move" tai hyllyn kortilla.' },
      'locations-rack-create': { title: 'Luo hyllykkö', steps: ['Avaa "Työkalut" > "Locations" > "Manage locations" ja valitse "Create rack" (managerit ja Placerings adminit).', 'Kirjoita nimi (esim. E9), hyllyjen määrä (1–20), alue ja tarkoitus (varasto tai keräily) ja valitse "Create". Hyllyt nimetään E9 H1, E9 H2 …', 'Hyllykön kortilla lisäät hyllyn valinnalla "Add shelf" ja poistat ylimmän tyhjän valinnalla "Remove shelf".'] },
      'locations-delete': { title: 'Poista sijainteja', steps: ['Avaa "Työkalut" > "Locations" > "Manage locations" (managerit ja Placerings adminit).', 'Yksi sijainti: avaa se ja valitse "Delete". Hyllykkö: avaa hyllykön kortti ja valitse "Delete rack".', 'Monta: suodata (esim. alue ja "Only empty"), valitse "Select all in the search" tai rivit ja valitse "Delete selected".'], notes: 'Vain tyhjät sijainnit poistetaan; jos paikalla on lavoja tai tavaraa, se jää ja näet syyn. Poisto näkyy lokissa ja sen voi perua.' },
      'softwareload-start': { title: 'Aloita softwareload-tehtävä', steps: ['Avaa etusivulta "Työkalut" ja valitse "Softwareload". Välilehti "My task" on auki.', 'Valitse tyyppi "Softwareload + keyload", "Softwareload" tai "Keyload", ja valitse "In KIF" tai "Outside KIF".', 'Valitse kohde listalta kentässä "Target (storage location)". Listassa näkyy SAPin kuvaus ja se, kuuluuko sijainti TCD:lle vai TRR:lle. Kirjoita versio kenttään "Software version" ja valitse "Start".', 'Kello käy nyt. Skannaa jokainen pääte kenttään "Scan serial number". Voit valita "Break" ja "Resume", ja väärän sarjanumeron poistat roskakorilla.'], notes: 'Jos "Time card" on käynnissä, se pysäytetään, kun aloitat, jotta aikaa ei lasketa kahdesti. Jos käynnistät "Time card" -kellon, softwareload-tehtävä pitää tauon. KIF:ssä kaikki päätteet siirretään D005:n kautta ennen kohdetta. KIF:n ulkopuolella ne siirretään suoraan kohteeseen. Tyyppi, KIF ja kohde muistetaan seuraavaa kertaa varten. "Cancel" hylkää tehtävän tallentamatta aikaa ja siirtämättä mitään.' },
      'softwareload-failed': { title: 'Merkitse pääte epäonnistuneeksi', steps: ['Etsi pääte käynnissä olevan tehtäväsi luettelosta "Scanned serial numbers" ja valitse "Failed".', 'Kirjoita muistiinpanoon, mikä on vialla, esim. että se ei lataudu, ja valitse "Mark as failed".', 'Päätteen kohdalla näkyy nyt "Failed" ja muistiinpano. Valitse "Undo failed", jos se oli virhe.'], notes: 'Kun tehtävä päätetään, uusi pääte (materiaali päättyy -0) menee D000:aan ja blocked stockiin, ja käytetty (-R) menee D002:een. KIF:ssä ne kulkevat D005:n kautta. Jos materiaali ei ole -0 eikä -R, pääte on käsiteltävä käsin.' },
      'softwareload-edit': { title: 'Korjaa käynnissä oleva tehtävä', steps: ['Valitse "Edit task" käynnissä olevassa tehtävässäsi välilehdellä "My task". Painike toimii, kun kaikki skannaukset on tallennettu.', 'Korjaa tyyppi, "In KIF" tai "Outside KIF", kohde ja ohjelmistoversio. Kentät ovat samat kuin aloitettaessa, ja niissä ovat valitsemasi arvot.', 'Valitse "Save the correction". Tehtävä näyttää uudet valinnat, ja aika ja skannatut sarjanumerot säilyvät.'], notes: 'Voit korjata tehtävää niin kauan kuin se on käynnissä ja kunnes valitset "Finish task". Mitään ei siirretä SAPissa ennen sitä, joten päättäminen käyttää uusia valintoja. Jos valitset korjauksessa "In KIF", koko tehtävä kulkee D005:n kautta. SAPia odottavaa tehtävää ei voi korjata. Korjaus näkyy tehtävän kohdalla tilastoissa.' },
      'softwareload-finish': { title: 'Päätä ja siirrä SAPissa', steps: ['Kun kaikki päätteet on skannattu, valitse "Finish task". Sovellus hakee päätteet SAPista ja näyttää, miten ne siirretään. Mitään ei ole vielä siirretty, ja aika kulkee yhä.', 'Tarkista ryhmät: kohteeseen, epäonnistuneet uudet D000:aan ja blocked stockiin, epäonnistuneet käytetyt D002:een sekä ongelmat, esim. "Not found in SAP" tai blocked stock, joita ei siirretä. KIF:ssä kaikki kulkee D005:n kautta.', 'Valitse "Finish and move in SAP". Vahvistus näyttää ryhmät ja niiden määrät. Valitse "Finish and move": aika pysähtyy, ja sovellus siirtää kaikki päätteet SAPissa yhdellä kertaa. Älä sulje SAPia sillä aikaa.', 'Tulos näyttää jokaisen sarjanumeron lopputuloksen ja materiaaliasiakirjat. Valitse "Done".'], notes: 'Jos SAP ei vastaa, esim. koska olet kirjautunut ulos, valitse käynnissä olevassa tehtävässä tai päättämisnäkymässä "Stop the time now, move in SAP later". Aika pysähtyy, SAPista ei haeta mitään, ja tehtävä odottaa välilehdellä "Waiting for SAP". Se odottaa siellä myös, jos SAP suljetaan siirron aikana. Valitse "Continue in SAP", kun SAP on valmis: sovellus hakee päätteet ja näyttää ensin suunnitelman. Valitse "Move in SAP" ja vahvista, niin juuri näytetty suunnitelma siirretään. Jo siirrettyä ei siirretä uudelleen. Jos päätteet ovat SAPissa muualla kuin näkemässäsi suunnitelmassa, mitään ei siirretä ja uusi suunnitelma näytetään. Manageri voi valita "Give up" ja kirjoittaa syyn, jolloin loput merkitään luovutetuiksi.' },
      'softwareload-kif': { title: 'Siirrä KIF:iin', steps: ['Avaa "Työkalut" > "Softwareload" ja valitse välilehti "Move into KIF".', 'Skannaa tai liitä sarjanumerot, yksi riville. Voit myös kirjoittaa materiaaliasiakirjan kenttään "Or a material document", jolloin käytetään asiakirjan sarjanumeroita.', 'Valitse "Show overview". Sovellus hakee päätteet SAPista ja näyttää, mitä siirretään D005:een, mikä on jo siellä ja mitä ei voi siirtää.', 'Valitse "Move to D005". Tulos näyttää jokaisen sarjanumeron ja sen materiaaliasiakirjan.'], notes: 'Tällä siirrät päätteet D005:een etukäteen, ennen kuin ne ladataan. Blocked stockissa olevia päätteitä ja sarjanumeroita, joita ei löydy SAPista, ei siirretä.' },
      'softwareload-search': { title: 'Hae sarjanumerolla', steps: ['Avaa "Työkalut" > "Softwareload" ja valitse välilehti "Search serial number".', 'Skannaa tai kirjoita sarjanumero ja valitse "Search". Haku kattaa sekä TCD:n että TRR:n.', 'Jokainen lataus ja jokainen siirto KIF:iin näytetään: kuka, milloin, tyyppi, ohjelmisto, KIF:ssä tai KIF:n ulkopuolella, mistä ja mihin sekä materiaaliasiakirjat.'], notes: 'Jos pääte merkittiin epäonnistuneeksi, myös muistiinpano näkyy.' },
      'softwareload-stats': { title: 'Katso softwareload-tilastot', steps: ['Avaa "Työkalut" > "Softwareload" ja valitse välilehti "Statistics" (vain managerit).', 'Valitse jakso (tänään, tämä viikko, tämä kuukausi, viime kuukausi tai oma) ja halutessasi henkilö, tyyppi, ohjelmistoversio ja materiaali.', 'Näet ylhäällä jakson kommentit, tehtävien määrän, ladatut, epäonnistuneet ja päätteet tunnissa, taulukon henkilöittäin ja tyypeittäin, taulukon materiaaleittain sekä tehtävien luettelon aikoineen.'], notes: 'Vain managerit (eivät status managerit) näkevät tilastot, ja he näkevät koko tiimin tehtävät. Tahti laskee päätteet työtuntia kohden. Vain epäonnistuneiksi merkityt jätetään pois. SAP:n hylkäämät näytetään myös erikseen. Jos tehtävässä on useita materiaaleja, aika jaetaan niille päätteiden määrän mukaan.' },
      'softwareload-comment': { title: 'Lisää kommentti jaksolle', steps: ['Avaa "Työkalut" > "Softwareload", valitse välilehti "Statistics" ja valitse jakso, jota kommentti koskee.', 'Valitse "Add comment". Jakso on valittu kuukausi. Valitse toinen kuukausi kohdassa "Whole month" tai valitse "Own dates" alku- ja loppupäivineen.', 'Kirjoita materiaalinumero ja ohjelmistoversio, jos kommentti koskee vain niitä. Ilman niitä se koskee koko jaksoa.', 'Kirjoita kommentti, esim. että materiaalin uuden ohjelmiston lataaminen kesti kauemmin, ja valitse "Save the comment".'], notes: 'Jaksoon osuvat ja suodattimiin sopivat kommentit näytetään lukujen yläpuolella, ja tehtävät ja materiaalit, joita ne koskevat, saavat pienen puhekuplan. Valitse kommentin kohdalla "Edit" tai "Delete" muokataksesi tai poistaaksesi sen. Vain managerit voivat kirjoittaa, muokata ja poistaa kommentteja, ja ne kuuluvat tiimille. Se, kuka kirjoitti, muokkasi ja poisti ja milloin, tallennetaan.' },
      'softwareload-delete': { title: 'Poista tehtävä tai KIF-siirto', steps: ['Avaa "Työkalut" > "Softwareload". Päätetyn tehtävän poistat välilehdellä "Statistics": valitse tehtävä, jotta se avautuu, ja valitse "Delete".', 'KIF-siirron tai tehtävän löydät myös välilehdeltä "Search serial number": hae jollakin sen sarjanumerolla ja valitse rivillä "Delete". Latauksen rivillä "Delete" poistaa koko tehtävän, ei vain riviä.', 'Vahvistus näyttää, mitä poistetaan. Valitse "Delete". Luettelo päivittyy, eikä tehtävää tai siirtoa enää lasketa tilastoihin eikä hakuun.'], notes: 'Vain managerit voivat poistaa, ja vain omassa tiimissään. Käytä sitä esimerkiksi testidataan. SAPia ei muuteta: siirrot ja materiaaliasiakirjat ovat yhä SAPissa. Käynnissä olevaa tai SAPia odottavaa tehtävää ei voi poistaa. Se, kuka poisti mitä ja milloin, tallennetaan.' },
    },
  },
  sv: {
    title: 'Arbetsverktyg',
    summary: 'Arbetsverktyg finns bara i TCD- och TRR-hubben (hette tidigare Lagerstyrning). Det är en liten hubb med verktyg: Time card (stämpelkort: stämpla in och ut på dina uppgifter med start, paus och stopp; bara managers ser tiderna), Locations (placeringar: var pallarna står, ställa in pallar, ta den äldsta först och fylla på plockplatser), Stock count (kvartalets inventering av terminaler och tillbehör i plant D301 med skanning av serienummer, godkännande, SAP-inventeringsdokument, slutrapporter och ett arkiv över genomförda statusar) och Softwareload (skanna terminalerna du laddar på en uppgift med klocka, och appen flyttar dem i SAP när uppgiften avslutas; sök på ett serienummer, och managers ser statistik). Vyerna är på engelska.',
    where: 'Öppna rutan "Arbetsverktyg" på startsidan (bara i TCD- och TRR-hubben) och välj "Time card", "Locations", "Stock count" eller "Softwareload".',
    tasks: {
      timeclock: { title: 'Stämpla in och ut på en uppgift', steps: ['Öppna "Arbetsverktyg" på startsidan och välj "Time card".', 'Din uppgift i dag från schemat är redan vald. Välj en annan uppgift i listan, eller klicka på "New task" för att skapa en (den läggs också till i schemat).', 'Klicka på "Start". Klockan går, och du kan klicka på "Break" och "Resume" så ofta du vill. Pauser räknas inte.', 'Klicka på "Stop" när uppgiften är klar. För att gå vidare till en annan uppgift, välj den och klicka på "Switch task": den första sparas och den nya startar i ett och samma tryck.'], notes: 'Klockan sparas på M:, så den fortsätter om du stänger appen och kan stoppas från en annan dator. Har den gått i mer än 10 timmar frågar Stop när du verkligen slutade. Sparade tider kan bara ses av managers. "Cancel clock" kastar en klocka som startats av misstag.' },
      'timeclock-overview': { title: 'Se registrerade tider och statistik', steps: ['Öppna "Arbetsverktyg" > "Time card" och välj fliken "Overview and statistics" (bara managers).', 'Välj period (i dag, denna vecka, denna månad, förra månaden eller egen) och eventuellt en person eller en uppgift.', 'Se total tid, antal registreringar, tid per uppgift, per person och per dag, och vem som stämplat in just nu.', 'Ändra eller ta bort en registrering i listan längst ner. Ändringen sparas med ditt namn.'], notes: 'Bara managers (inte status managers) ser tiderna. Medarbetarna ser varken varandras eller sina egna sparade tider.' },
      'start-status': { title: 'Starta en status', steps: ['Öppna "Arbetsverktyg" på startsidan och välj "Stock count".', 'Klicka på "Start new status", välj år och kvartal och klicka på "Start status". Innan du startar kan du köra "Check SAP errors" så att fel i SAP rättas före inventeringen.', 'Nu kan alla i teamet skapa inventeringar i statusen. Bara en status åt gången kan pågå.'], notes: 'Bara managers och status managers kan starta, låsa och ta bort en status.' },
      'create-count': { title: 'Skapa en inventering', steps: ['Öppna "Arbetsverktyg" > "Stock count" och klicka på "New count" (det kräver en pågående status och att SAP är öppet).', 'Välj lagerplatser, Unblocked eller Blocked, och om det gäller terminaler eller tillbehör. Blocked-lager inventeras bara i D000.', 'Klicka på "Fetch from SAP". Saldon och serienummer för hela D301 hämtas (ungefär en minut), och du ser vad som ska räknas.', 'Ge inventeringen ett namn och klicka på "Create count". Du blir ansvarig, och kollegor kan be om att få vara med.'], notes: 'Varje lagerplats och lagertyp inventeras bara i en inventering per status. SAP läses bara när en inventering skapas.' },
      'blocked-unblocked': { title: 'Räkna blocked och unblocked lager', steps: ['Blocked lager finns bara på D000 och räknas i en egen inventering, eftersom det bokförs separat i SAP.', 'Klicka på "New count", välj "Blocked" under Stock type och D000, och klicka på "Fetch from SAP". Unblocked lager räknas i en annan inventering.', 'Skannar du ett blocked serienummer i en unblocked inventering (eller tvärtom), ser du vilken inventering det hör till.'], notes: 'Tillbehör räknas också bara i D000. I översikten kan du markera "Show only blocked".' },
      'long-serials': { title: 'Långa serienummer till SAP-dokument', steps: ['Bara TCD: öppna "Arbetsverktyg" > "Stock count" och välj fliken "Serial number rules". En manager lägger till de nya terminalerna (INT…-0) vars SAP-dokument behöver det långa serienumret (ZMS_LONG_SERNO).', 'I inventeringen: välj fliken "Overview" eller "To count document" och klicka på "Long" vid materialet. De långa numren slås upp i SAP och kopieras, klara att klistra in i SAP.', 'Material utan regel kopieras med de korta numren via "Copy".'], notes: 'Skanning använder alltid det korta numret, och blocked lager (D000) använder alltid de korta numren. Har SAP inget långt nummer kopieras det korta, och du får besked.' },
      'scan-serials': { title: 'Skanna serienummer och räkna antal', steps: ['Öppna inventeringen och välj fliken "Scan serial numbers". Välj eller skriv platsen (t.ex. "Pallet 14.2").', 'Skanna serienumren. Du ser direkt om numret hittades, saknas i SAP, hör till en annan inventering eller står på fel plats.', 'Varor utan serienummer räknas på fliken "Accessories and count lists": välj materialet, klicka på en plats och skriv antalet.', 'Ångra en felskanning med "Undo (Ctrl+Z)", eller ta bort den under "Remove serial number".'], notes: 'Skanningarna sparas först lokalt och skickas till den delade enheten, även om anslutningen bryts en stund. Platserna från TCD:s placeringsark är bara förslag.' },
      'submit-material': { title: 'Räkna ett material och skicka det för godkännande', steps: ['Välj materialet under "Material in focus". Det låses till dig, så att ingen annan räknar det samtidigt.', 'Skanna eller räkna klart materialet. Vill du hjälpa en kollega, klicka på "Ask to help count".', 'Klicka på "Send for approval". Finns det en differens bekräftar du den och skriver gärna en kommentar.'], notes: 'Ett godkänt material försvinner från listorna, och siffrorna fryses.' },
      'approve-materials': { title: 'Godkänn material och avsluta en inventering', steps: ['Öppna inventeringen och välj fliken "Approval". "Approve all without a difference" godkänner alla material som stämmer.', 'Gå igenom materialen med differens: klicka på "Approve", eller "Send back" med en kommentar om de ska räknas om.', 'När allt är godkänt klickar den ansvarige på "Close". Excel-rapporten skapas under "Excel report".'], notes: 'Godkännandet fryser SAP-antal, räknat antal och differens. "Reset" tar bort godkännandet igen.' },
      'sap-documents': { title: 'Skapa och bokför SAP-inventeringsdokument', steps: ['Öppna inventeringen och välj fliken "To count document". Klicka på "Fetch today\'s SAP figures" samma dag som dokumentet skapas.', 'Markera godkända material och klicka på "Create SAP document". SAP öppnas och du trycker själv på F8. Klicka sedan på "Print".', 'En admin (inte den som skapade dokumentet) klickar på "Enter quantity". Serienummer går till ZMS_COUNT_SERIAL (SAP:s serienummer i dag minus de som saknades vid godkännandet), antal till MI04.', 'Till sist klickar en manager på "Post". Materialdokumentet visas, och materialet står som "Posted in SAP".'], notes: 'Högst 20 material per dokument. Nya terminaler får ett eget dokument var, och serienummer- och antalsmaterial blandas aldrig. Programmet fyller i SAP, men du trycker alltid själv på F8, Save eller Post. Ett dokument kan tas bort så länge inga antal har lagts in.' },
      'lock-status': { title: 'Godkänn och lås statusen', steps: ['Öppna statusen med "See details". Checklistan visar vad som saknas: öppna inventeringar och material som inte är godkända eller bokförda.', 'När det står "Everything is ready", klicka på "Approve and lock status" och bekräfta. Slutrapporten för statusen och en rapport per inventering sparas.', 'Statusen flyttas till "Archive". Om något måste rättas, klicka på "Unlock" och skriv varför. Nästa låsning ger version 2 av rapporten.'] },
      archive: { title: 'Arkiv och differens i procent', steps: ['Öppna "Arbetsverktyg" > "Stock count" och välj fliken "Archive". Där finns alla godkända och låsta statusar med sina rapporter.', 'Klicka på "See details". Differensen visas i procent av SAP-saldot, både i styck och DKK. Både över och under räknas som differens.', 'Materialtabellen visar SAP, räknat, differens, godkännande och dokument. Klicka på ett dokumentnummer för att se det i SAP (MI03 eller materialdokumentet, bara visning).'], notes: 'Alla i teamet kan se arkivet.' },
      'sap-check': { title: 'Kontrollera SAP-fel före en status', steps: ['Öppna "Arbetsverktyg" > "Stock count" och välj fliken "Check SAP errors". Välj TCD, TRR eller hela D301 och klicka på "Check SAP now".', 'Listan visar t.ex. lager där antalet inte stämmer med serienumren, serienummer på flera platser och lager utan serienummer. Resultatet jämförs med SAP-rapporten ZMS_STOCK_SER_CHK2.', 'Klicka på "Make mail to the SAP team" för att skicka felen till den som ska rätta dem. Mejlet öppnas i Outlook och du skickar det själv.'] },
      'warehouse-roles': { title: 'Utse en admin, en status manager eller en Placerings admin', steps: ['Öppna "Manager Panel" och välj fliken "Behörigheter". Kortet "Roller i Arbetsverktyg" visas bara i TCD- och TRR-hubben.', 'Under "Inventering": välj "Admin" för en kollega som ska vara med i alla inventeringar utan att ansöka, godkänna deltagare och lägga in antal och serienummer på SAP-dokument, eller "Status manager" för någon som ska ha samma rättigheter som en manager i inventeringen.', 'Under "Placeringar": välj "Placerings admin" för en kollega som får underhålla placeringar och ångra åtgärder i loggen.'], notes: 'Bara managers kan ändra rollerna, och managers har alltid alla rättigheter. Den som skapar ett SAP-dokument kan aldrig själv lägga in antalen på det. En status manager är inte Placerings admin bara därför.' },
      'warehouse-roles-info': { title: 'Roller i inventeringen och Placeringar', steps: ['Admin i inventeringen: är med i alla inventeringar utan att ansöka, godkänner deltagare och lägger in antal och serienummer på SAP-dokument med "Enter quantity". Det är alltid någon annan än den som skapade dokumentet.', 'Status manager: har samma rättigheter som en manager i inventeringen, t.ex. att starta, låsa och ta bort en status, godkänna material och bokföra SAP-dokument.', 'Placerings admin: får underhålla placeringar och ångra åtgärder i loggen i Placeringar.'], notes: 'Bara managers utser de tre rollerna (i "Manager Panel" under "Behörigheter"). Fråga din manager om du behöver någon av dem.' },
      'locations-put-away': { title: 'Sätt en pall på plats', steps: ['Öppna "Arbetsverktyg" på startsidan, välj "Locations" och klicka på "Put a pallet away".', 'Skanna eller skriv 49/50-numret och klicka på "Fetch from SAP". Material, antal och serienummer fylls i från SAP. Utan SAP skriver du material och antal själv.', 'Välj en av de föreslagna platserna (fast plats, nära samma material eller ledig) eller skriv platsen.', 'Klicka på "Add next pallet" för fler pallar och "Save all" till sist.'], notes: 'Datumet är i dag och kan ändras. Reserverade och avaktiverade platser föreslås aldrig. TCD och TRR har egna placeringar.' },
      'locations-take': { title: 'Ta en pall (FIFO)', steps: ['Öppna "Arbetsverktyg" > "Locations" och klicka på "Take".', 'Sök eller skanna materialet. Pallarna visas med den äldsta först, så ni kör FIFO.', 'Klicka på "Take the whole pallet", eller skriv ett antal och klicka på "Take X". Väljer du en yngre pall visas den äldre och du kan klicka på "Take anyway".', 'Finns materialet på hyllor visas de under "On shelves": skriv ett antal och klicka på "Take X", eller klicka på "Take all".'] },
      'locations-refill': { title: 'Fyll på en plockplats', steps: ['När en låda vid arbetsstationen är tom: öppna "Arbetsverktyg" > "Locations" och klicka på "Refill a pick place".', 'Välj plockplatsen (och materialet om platsen har flera). Förslaget är den äldsta reservpallen med samma material (FIFO).', 'Hämta lådan och klicka på "Refilled from …". Skriv ett antal om du bara tog en del av pallen. Väljer du en yngre pall visas den äldre och du kan klicka på "Refill anyway".'], notes: 'Plockplatser har ingen egen FIFO och inget antal; FIFO gäller pallarna de fylls på från. Du kan också fråga Hubert: "vad fyller jag på H26 med?".' },
      'locations-find': { title: 'Hitta ett material', steps: ['Öppna "Arbetsverktyg" > "Locations" och skriv i sökfältet: materialnummer, beskrivning, placering, 49/50-nummer eller serienummer. Med en skanner öppnas en enda träff direkt.', 'Materialkortet visar arbetsstation, plockplats, reservpallar med den äldsta först och det totala antalet. Platskortet visar vad som står på platsen.', 'På pallkortet kan du klicka på "Edit", "Move" eller "Change storage location". Allt hamnar i historiken.'], notes: 'Du kan också fråga Hubert, t.ex. "var står R162-0717?".' },
      'locations-create': { title: 'Skapa placeringar', steps: ['Öppna "Arbetsverktyg" > "Locations" och klicka på "Manage locations" (managers och Placerings admins).', 'Klicka på "Create location" för en plats: namn, typ, syfte (reserve, pick place, work station eller reserved) och eventuella fasta material. Typen styr platsen: en pallplats tar 1 pall, ett golv har ingen gräns och en hylla har material och antal. En plockplats behöver sina material.', 'Klicka på "Create series" för många platser på en gång, t.ex. prefix C, gångar 1–20 och platser 1–6 ger C1.1 … C20.6.', 'Ändra, avaktivera eller sätt etiketter (t.ex. "Sluse oppe") från listan. Allt kan rättas i efterhand.'], notes: 'TRR skapar alla placeringar här från grunden; TCD kan importera placeringsarket.' },
      'locations-import': { title: 'Importera placeringsarket', steps: ['Bara TCD: öppna "Arbetsverktyg" > "Locations" > "Manage locations" och klicka på "Import the placement sheet". SAP måste vara öppet.', 'Klicka på "Read the sheet and check in SAP". Hubben läser det senaste placeringsarket på M: (bara läsning) och hämtar alla materialbeskrivningar från SAP.', 'Gå igenom förhandsvisningen: antal placeringar och pallar samt varningar, t.ex. material som inte finns i SAP. Klicka på "Import".'], notes: 'Arket kan importeras igen med "Replace all" tills placeringarna används. Inventeringen läser fortfarande själva arket tills ni bestämmer er för att använda placeringarna.' },
      'locations-shelf-put': { title: 'Lägg på hylla', steps: ['Öppna "Arbetsverktyg" > "Locations" och klicka på "Put on shelf".', 'Skanna eller skriv hyllan, t.ex. "E9 H5" (reol E9, hylla 5).', 'Välj materialet (förslag med beskrivning medan du skriver) och skriv antalet – eller skanna 49/50-numret och klicka på "Get from SAP". Finns materialet redan där läggs antalet till. Klicka på "Save". Har numret flera material visas de som knappar med antal: spara dem ett i taget, så väljs nästa av sig själv.'], notes: 'En hylla har material och antal – ingen ålder eller FIFO. Ta från en hylla under "Take" och flytta mellan hyllor under "Move" eller på hyllans kort.' },
      'locations-rack-create': { title: 'Skapa en reol', steps: ['Öppna "Arbetsverktyg" > "Locations" > "Manage locations" och klicka på "Create rack" (managers och Placerings admins).', 'Skriv namnet (t.ex. E9), antal hyllor (1–20), området och syftet (lager eller plock) och klicka på "Create". Hyllorna heter E9 H1, E9 H2 …', 'På reolens kort lägger du till en hylla med "Add shelf" och tar bort den översta tomma med "Remove shelf".'] },
      'locations-delete': { title: 'Ta bort placeringar', steps: ['Öppna "Arbetsverktyg" > "Locations" > "Manage locations" (managers och Placerings admins).', 'En placering: öppna den och klicka på "Delete". En reol: öppna reolens kort och klicka på "Delete rack".', 'Många: filtrera (t.ex. område och "Only empty"), klicka på "Select all in the search" eller välj raderna, och klicka på "Delete selected".'], notes: 'Bara tomma placeringar tas bort; står det pallar eller varor kvar blir platsen kvar och du får veta varför. Borttagningen syns i loggen och kan ångras.' },
      'softwareload-start': { title: 'Starta en softwareload-uppgift', steps: ['Öppna "Arbetsverktyg" på startsidan och välj "Softwareload". Fliken "My task" är öppen.', 'Välj typen "Softwareload + keyload", "Softwareload" eller "Keyload", och välj "In KIF" eller "Outside KIF".', 'Välj målet i listan under "Target (storage location)". Listan visar SAP:s beskrivning och om platsen hör till TCD eller TRR. Skriv versionen under "Software version" och klicka på "Start".', 'Klockan går nu. Skanna varje terminal i fältet "Scan serial number". Du kan klicka på "Break" och "Resume", och ett fel serienummer tar du bort med papperskorgen.'], notes: 'Går "Time card", stoppas den när du startar, så att tiden inte räknas två gånger. Startar du "Time card", pausas softwareload-uppgiften. I KIF flyttas alla terminaler via D005 innan de kommer till målet. Utanför KIF flyttas de direkt till målet. Typ, KIF och mål sparas till nästa gång. "Cancel" kastar uppgiften utan att tiden sparas eller något flyttas.' },
      'softwareload-failed': { title: 'Markera en terminal som misslyckad', steps: ['Hitta terminalen i listan "Scanned serial numbers" i din pågående uppgift och klicka på "Failed".', 'Skriv i anteckningen vad som är fel, t.ex. att den inte laddar, och klicka på "Mark as failed".', 'Terminalen visas nu med "Failed" och anteckningen. Klicka på "Undo failed" om det var ett misstag.'], notes: 'När uppgiften avslutas går en ny terminal (materialet slutar på -0) till D000 och blocked stock, och en begagnad (-R) går till D002. I KIF går de via D005. Är materialet varken -0 eller -R måste terminalen hanteras manuellt.' },
      'softwareload-edit': { title: 'Rätta en pågående uppgift', steps: ['Klicka på "Edit task" i din pågående uppgift under "My task". Knappen fungerar när alla skanningar är sparade.', 'Rätta typen, "In KIF" eller "Outside KIF", målet och programvaruversionen. Fälten är desamma som vid start och är ifyllda med det du valde.', 'Klicka på "Save the correction". Uppgiften visar de nya valen, och tiden och de skannade serienumren står kvar.'], notes: 'Du kan rätta uppgiften så länge den pågår och tills du klickar på "Finish task". Inget flyttas i SAP före dess, så avslutningen använder de nya valen. Väljer du "In KIF" i rättelsen går hela uppgiften via D005. En uppgift som väntar på SAP kan inte rättas. Rättelsen visas vid uppgiften i statistiken.' },
      'softwareload-finish': { title: 'Avsluta och flytta i SAP', steps: ['När alla terminaler är skannade, klicka på "Finish task". Appen slår upp terminalerna i SAP och visar hur de kommer att flyttas. Inget är flyttat än, och tiden går fortfarande.', 'Kontrollera grupperna: till målet, misslyckade nya till D000 och blocked stock, misslyckade begagnade till D002 och problem, t.ex. "Not found in SAP" eller blocked stock, som inte flyttas. I KIF går allt via D005.', 'Klicka på "Finish and move in SAP". Bekräftelsen visar grupperna med antal. Klicka på "Finish and move": tiden stoppar och appen flyttar alla terminaler i SAP i ett svep. Stäng inte SAP under tiden.', 'Resultatet visar varje serienummer med utfall och materialdokument. Klicka på "Done".'], notes: 'Svarar SAP inte, t.ex. för att du är utloggad, klicka på "Stop the time now, move in SAP later" i den pågående uppgiften eller på avslutsskärmen. Tiden stoppar, inget slås upp i SAP, och uppgiften väntar på fliken "Waiting for SAP". Där väntar den också om SAP stängs under flytten. Klicka på "Continue in SAP" när SAP är redo: appen slår upp terminalerna och visar planen först. Klicka på "Move in SAP" och bekräfta, så flyttas exakt den plan som visades. Det som redan är flyttat flyttas inte igen. Har SAP terminalerna någon annanstans än i planen du såg, flyttas inget och den nya planen visas. En manager kan klicka på "Give up" och skriva en motivering, så att resten står som uppgivet.' },
      'softwareload-kif': { title: 'Flytta in i KIF', steps: ['Öppna "Arbetsverktyg" > "Softwareload" och välj fliken "Move into KIF".', 'Skanna eller klistra in serienumren, ett per rad. Du kan också skriva ett materialdokument under "Or a material document", så används dokumentets serienummer.', 'Klicka på "Show overview". Appen slår upp terminalerna i SAP och visar vad som flyttas till D005, vad som redan står där och vad som inte kan flyttas.', 'Klicka på "Move to D005". Resultatet visar varje serienummer med materialdokumentet.'], notes: 'Använd det för att flytta terminaler till D005 i förväg, innan de ska laddas. Terminaler i blocked stock och serienummer som inte finns i SAP flyttas inte.' },
      'softwareload-search': { title: 'Sök på ett serienummer', steps: ['Öppna "Arbetsverktyg" > "Softwareload" och välj fliken "Search serial number".', 'Skanna eller skriv serienumret och klicka på "Search". Sökningen täcker både TCD och TRR.', 'Varje laddning och varje flytt in i KIF visas med vem, när, typ, programvara, i KIF eller utanför KIF, från och till och materialdokumenten.'], notes: 'Markerades terminalen som misslyckad visas anteckningen också.' },
      'softwareload-stats': { title: 'Visa softwareload-statistik', steps: ['Öppna "Arbetsverktyg" > "Softwareload" och välj fliken "Statistics" (bara managers).', 'Välj period (i dag, denna vecka, denna månad, förra månaden eller egen) och eventuellt en person, en typ, en programvaruversion och ett material.', 'Se kommentarerna till perioden överst, antal uppgifter, laddade, misslyckade och terminaler per timme, en tabell per person och typ, en tabell per material och listan över uppgifterna med tider.'], notes: 'Bara managers (inte status managers) ser statistiken, och de ser hela teamets uppgifter. Takten räknar terminaler per arbetstimme. Bara de som markerats som misslyckade räknas inte med. De som SAP avvisade visas också för sig. Har en uppgift flera material, fördelas tiden på dem efter antal terminaler.' },
      'softwareload-comment': { title: 'Lägg till en kommentar till en period', steps: ['Öppna "Arbetsverktyg" > "Softwareload", välj fliken "Statistics" och välj den period som kommentaren gäller.', 'Klicka på "Add comment". Perioden är den valda månaden. Välj en annan månad under "Whole month", eller välj "Own dates" med från och till.', 'Skriv ett materialnummer och en programvaruversion om kommentaren bara gäller dem. Utan dem gäller den hela perioden.', 'Skriv kommentaren, t.ex. att ny programvara till ett material tog längre tid att ladda, och klicka på "Save the comment".'], notes: 'Kommentarer som träffar perioden och passar filtren visas ovanför siffrorna, och de uppgifter och material som de gäller får en liten pratbubbla. Klicka på "Edit" eller "Delete" vid en kommentar för att ändra eller ta bort den. Bara managers kan skriva, ändra och ta bort kommentarer, och de gäller för teamet. Vem som skrev, ändrade och tog bort och när sparas.' },
      'softwareload-delete': { title: 'Ta bort en uppgift eller KIF-flytt', steps: ['Öppna "Arbetsverktyg" > "Softwareload". En avslutad uppgift tar du bort på fliken "Statistics": klicka på uppgiften så att den öppnas och klicka på "Delete".', 'En flytt in i KIF eller en uppgift hittar du också på fliken "Search serial number": sök på ett av serienumren och klicka på "Delete" på raden. "Delete" på en laddning tar bort hela uppgiften, inte bara raden.', 'Bekräftelsen visar vad som tas bort. Klicka på "Delete". Listan uppdateras, och uppgiften eller flytten räknas inte längre med i statistiken och sökningen.'], notes: 'Bara managers kan ta bort, och bara i sitt eget team. Använd det t.ex. för testdata. SAP ändras inte: flyttarna och materialdokumenten finns kvar i SAP. En uppgift som pågår eller väntar på SAP kan inte tas bort. Vem som tog bort vad och när sparas.' },
    },
  },
}

module.exports = { WAREHOUSE_LOCALIZED }
